// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

import { IUniswapV2Pair } from "../vendor/uniswap-v2-core/interfaces/IUniswapV2Pair.sol";

/// @dev Uniswap V2 TWAP helpers (cumulative price oracles). See https://docs.uniswap.org/contracts/v2/concepts/core-concepts/oracles
library UniswapV2TwapLib {
    uint256 private constant Q112 = 1 << 112;

    /// @dev Canonical Uniswap V2 pair init code hash (mainnet / production routers on Arbitrum One).
    /// Vendored `UniswapV2Factory` deployed on Arbitrum Sepolia uses different bytecode — use `factory.getPair` there.
    bytes32 private constant PAIR_INIT_CODE_HASH =
        0x96e8ac4277198ff8b6f785478aa9a39f403cb768dd02cbee326c3e7da348845f;

    struct Observation {
        uint32 timestamp;
        uint256 price0Cumulative;
        uint256 price1Cumulative;
    }

    function pairFor(address factory, address tokenA, address tokenB) internal pure returns (address pair) {
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        pair = address(
            uint160(
                uint256(
                    keccak256(abi.encodePacked(hex"ff", factory, keccak256(abi.encodePacked(token0, token1)), PAIR_INIT_CODE_HASH))
                )
            )
        );
    }

    /// @notice Extrapolates cumulative prices to the current block (same pattern as Uniswap periphery oracle samples).
    function currentCumulativePrices(address pair)
        internal
        view
        returns (uint256 price0Cumulative, uint256 price1Cumulative, uint32 blockTimestamp)
    {
        blockTimestamp = uint32(block.timestamp);
        IUniswapV2Pair uniPair = IUniswapV2Pair(pair);
        (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast) = uniPair.getReserves();
        price0Cumulative = uint256(uniPair.price0CumulativeLast());
        price1Cumulative = uint256(uniPair.price1CumulativeLast());
        unchecked {
            uint32 timeElapsed = blockTimestamp - blockTimestampLast;
            if (timeElapsed > 0 && reserve0 != 0 && reserve1 != 0) {
                price0Cumulative += (uint256(reserve1) * Q112 / uint256(reserve0)) * timeElapsed;
                price1Cumulative += (uint256(reserve0) * Q112 / uint256(reserve1)) * timeElapsed;
            }
        }
    }

    /// @dev TWAP output for `amountIn` of `tokenIn` sold for the other pair token, using stored `obs` as the window start.
    function quoteTwapAmountOut(
        address pair,
        address tokenIn,
        uint256 amountIn,
        Observation memory obs,
        uint32 nowTimestamp
    ) internal view returns (uint256 amountOut) {
        if (obs.timestamp == 0 || nowTimestamp <= obs.timestamp || amountIn == 0) return 0;

        (uint256 price0CumulativeNow, uint256 price1CumulativeNow,) = currentCumulativePrices(pair);
        address token0 = IUniswapV2Pair(pair).token0();
        uint32 timeElapsed = nowTimestamp - obs.timestamp;
        unchecked {
            if (tokenIn == token0) {
                uint256 price0Delta = price0CumulativeNow - obs.price0Cumulative;
                if (price0Delta == 0) return 0;
                uint224 price0Average = uint224(price0Delta / timeElapsed);
                amountOut = (amountIn * uint256(price0Average)) >> 112;
            } else {
                uint256 price1Delta = price1CumulativeNow - obs.price1Cumulative;
                if (price1Delta == 0) return 0;
                uint224 price1Average = uint224(price1Delta / timeElapsed);
                amountOut = (amountIn * uint256(price1Average)) >> 112;
            }
        }
    }

    /// @dev Apply pool fees and trade price impact to the historical marginal price.
    function quoteExecutableTwapAmountOut(
        address pair, address tokenIn, uint256 amountIn, Observation memory obs, uint32 nowTimestamp
    ) internal view returns (uint256) {
        uint256 marginalOut = quoteTwapAmountOut(pair, tokenIn, amountIn, obs, nowTimestamp);
        (uint112 reserve0, uint112 reserve1,) = IUniswapV2Pair(pair).getReserves();
        uint256 reserveIn = tokenIn == IUniswapV2Pair(pair).token0() ? reserve0 : reserve1;
        if (reserveIn == 0 || amountIn > (type(uint256).max - reserveIn * 1000) / 997) return 0;
        return Math.mulDiv(marginalOut, reserveIn * 997, reserveIn * 1000 + amountIn * 997);
    }

    /// @dev Constant-product spot output (997/1000 fee), used before TWAP window is warm or as fallback.
    function spotAmountOut(address pair, address tokenIn, uint256 amountIn) internal view returns (uint256 amountOut) {
        if (amountIn == 0) return 0;
        IUniswapV2Pair uniPair = IUniswapV2Pair(pair);
        (uint112 reserve0, uint112 reserve1,) = uniPair.getReserves();
        address token0 = uniPair.token0();
        (uint256 reserveIn, uint256 reserveOut) =
            tokenIn == token0 ? (uint256(reserve0), uint256(reserve1)) : (uint256(reserve1), uint256(reserve0));
        if (reserveIn == 0 || reserveOut == 0) return 0;
        unchecked {
            uint256 amountInWithFee = amountIn * 997;
            amountOut = amountInWithFee * reserveOut / (reserveIn * 1000 + amountInWithFee);
        }
    }
}

contracts/LPVestingLock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @notice Holds Uniswap V2 LP tokens until a fixed 3-year cliff, then beneficiary may withdraw.
contract LPVestingLock is AccessControl {
    using SafeERC20 for IERC20;

    bytes32 public constant BENEFICIARY_ROLE = keccak256("BENEFICIARY_ROLE");

    IERC20 public immutable lpToken;
    uint256 public immutable cliff;

    error ZeroAddress();
    error LockNotElapsed();
    error ZeroAmount();
    error AmountExceedsBalance();

    event Released(address to, uint256 amount);

    constructor(address lpToken_, address beneficiary, address admin) {
        if (lpToken_ == address(0) || beneficiary == address(0) || admin == address(0)) revert ZeroAddress();
        lpToken = IERC20(lpToken_);
        cliff = block.timestamp + 3 * 365 days;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(BENEFICIARY_ROLE, beneficiary);
    }

    /// @notice After cliff, transfers entire LP balance to `to`.
    function release(address to) external onlyRole(BENEFICIARY_ROLE) {
        _release(to, lpToken.balanceOf(address(this)));
    }

    /// @notice After cliff, transfers `amount` of LP tokens to `to`.
    function release(address to, uint256 amount) external onlyRole(BENEFICIARY_ROLE) {
        _release(to, amount);
    }

    function _release(address to, uint256 amount) internal {
        if (block.timestamp < cliff) revert LockNotElapsed();
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (amount > lpToken.balanceOf(address(this))) revert AmountExceedsBalance();
        lpToken.safeTransfer(to, amount);
        emit Released(to, amount);
    }
}

contracts/MarketRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { BeaconProxy } from "@openzeppelin/contracts/proxy/beacon/BeaconProxy.sol";
import { UpgradeableBeacon } from "@openzeppelin/contracts/proxy/beacon/UpgradeableBeacon.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { IMarketRegistry } from "./interfaces/IMarketRegistry.sol";
import { IRouletteEngine } from "./interfaces/IRouletteEngine.sol";
import { BankVault4626 } from "./BankVault4626.sol";

contract MarketRegistry is AccessControl, IMarketRegistry {
    bytes32 public constant MARKET_FACTORY_ROLE = keccak256("MARKET_FACTORY_ROLE");

    mapping(uint32 => MarketConfig) private _markets;
    mapping(address => uint32) private _assetToMarket;
    uint32 private _marketCount;
    address public override vaultBeacon;
    address public immutable override ENGINE;
    address public immutable override SIDE_BET;

    error ZeroAddress();
    error ZeroImplementation();
    error InvalidMarketId();
    error AssetAlreadyRegistered();

    event VaultBeaconUpdated(address previousBeacon, address newBeacon);

    struct VaultInit {
        address asset;
        string bankName;
        string bankSymbol;
        uint32 marketId;
        address engine;
        address bankAdmin;
        uint256 minBet;
        address sideBet;
    }

    constructor(address admin, address engine_, address sideBet_) {
        if (admin == address(0) || engine_ == address(0) || sideBet_ == address(0)) revert ZeroAddress();
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(MARKET_FACTORY_ROLE, admin);
        ENGINE = engine_;
        SIDE_BET = sideBet_;
    }

    function previewNextMarketId() external view returns (uint32) {
        unchecked {
            return _marketCount + 1;
        }
    }

    function setVaultBeacon(address newBeacon) external onlyRole(MARKET_FACTORY_ROLE) {
        if (newBeacon == address(0)) revert ZeroAddress();
        if (newBeacon.code.length == 0) revert ZeroImplementation();
        // Touch the beacon to ensure it at least implements `implementation()`.
        UpgradeableBeacon(newBeacon).implementation();

        address previous = vaultBeacon;
        vaultBeacon = newBeacon;
        emit VaultBeaconUpdated(previous, newBeacon);
    }

    /// @dev Call `setVaultBeacon` before any `createMarket`.
    /// @dev Vault share `name` is `BRB ` + asset `name()`, share `symbol` is `brb` + asset `symbol()` (via `IERC20Metadata`).
    function createMarket(CreateMarketParams calldata params)
        external
        onlyRole(MARKET_FACTORY_ROLE)
        returns (uint32 marketId, address bank)
    {
        if (params.asset == address(0) || params.bankAdmin == address(0) || params.minBet == 0) revert ZeroAddress();
        if (_assetToMarket[params.asset] != 0) revert AssetAlreadyRegistered();

        IERC20Metadata assetMeta = IERC20Metadata(params.asset);
        string memory bankName = string.concat("BRB ", assetMeta.name());
        string memory bankSymbol = string.concat("brb", assetMeta.symbol());

        uint32 nextId = _marketCount + 1;
        address beacon = vaultBeacon;
        address engine = ENGINE;
        VaultInit memory p;
        p.asset = params.asset;
        p.bankName = bankName;
        p.bankSymbol = bankSymbol;
        p.marketId = nextId;
        p.engine = engine;
        p.bankAdmin = params.bankAdmin;
        p.minBet = params.minBet;
        p.sideBet = SIDE_BET;

        bytes memory initData = _encodeVaultInitData(p);
        bank = _deployVault(beacon, initData);

        marketId = _registerNextMarket(params.asset, bank);
        IRouletteEngine(engine).registerMarketFromRegistry(marketId, bank);
    }

    function _encodeVaultInitData(VaultInit memory p) private pure returns (bytes memory) {
        return abi.encodeWithSelector(
            BankVault4626.initialize.selector,
            BankVault4626.InitializeParams({
                assetToken: p.asset,
                name: p.bankName,
                symbol: p.bankSymbol,
                marketId: p.marketId,
                engine: p.engine,
                admin: p.bankAdmin,
                minBet: p.minBet,
                sideBetController: p.sideBet
            })
        );
    }

    function _deployVault(address beacon, bytes memory initData) private returns (address bank) {
        bank = address(new BeaconProxy(beacon, initData));
    }

    function _registerNextMarket(address asset, address bank) internal returns (uint32 marketId) {
        if (asset == address(0) || bank == address(0)) revert ZeroAddress();

        uint32 next;
        unchecked {
            next = _marketCount + 1;
        }

        _markets[next] = MarketConfig({ asset: asset, bank: bank });
        _assetToMarket[asset] = next;
        _marketCount = next;

        return next;
    }

    function assetToMarket(address asset) external view returns (uint32 marketId) {
        return _assetToMarket[asset];
    }

    function marketCount() external view returns (uint32) {
        return _marketCount;
    }

    function getMarket(uint32 marketId) external view returns (MarketConfig memory config) {
        if (marketId == 0 || marketId > _marketCount) revert InvalidMarketId();
        return _markets[marketId];
    }
}

contracts/ProtocolTimelock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { Address } from "@openzeppelin/contracts/utils/Address.sol";

/// @notice Minimal timelock for privileged calls (e.g. `UpgradeableBeacon.upgradeTo`, registry admin).
/// @dev Proposer queues; executor runs after `DELAY`. Admin can cancel. Does not wrap ownership transfer;
/// deploy beacons / governance contracts with this contract as owner, then queue upgrades here.
contract ProtocolTimelock is AccessControl {
    uint256 public constant DELAY = 24 hours;

    bytes32 public constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
    bytes32 public constant EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");

    /// @dev Operation id => timestamp when executable; 0 = not queued.
    mapping(bytes32 => uint256) public queuedUntil;

    error ZeroAddress();
    error AlreadyQueued();
    error NotQueued();
    error TooEarly();
    error WrongMsgValue();

    event OperationQueued(bytes32 id, address target, uint256 value, uint256 salt, uint256 executeAfter);
    event OperationExecuted(bytes32 id, address target, uint256 value, uint256 salt);
    event OperationCancelled(bytes32 id);

    constructor(address admin_, address proposer_, address executor_) {
        if (admin_ == address(0) || proposer_ == address(0) || executor_ == address(0)) revert ZeroAddress();
        _grantRole(DEFAULT_ADMIN_ROLE, admin_);
        _grantRole(PROPOSER_ROLE, proposer_);
        _grantRole(EXECUTOR_ROLE, executor_);
    }

    function operationId(address target, uint256 value, bytes calldata data, uint256 salt) public pure returns (bytes32) {
        return keccak256(abi.encode(target, value, data, salt));
    }

    function queue(address target, uint256 value, bytes calldata data, uint256 salt) external onlyRole(PROPOSER_ROLE) {
        bytes32 id = operationId(target, value, data, salt);
        if (queuedUntil[id] != 0) revert AlreadyQueued();
        uint256 eta = block.timestamp + DELAY;
        queuedUntil[id] = eta;
        emit OperationQueued(id, target, value, salt, eta);
    }

    /// @notice `msg.value` must equal `value` so native currency is supplied at execution time (no pre-deposit on the timelock).
    function execute(address target, uint256 value, bytes calldata data, uint256 salt) external payable onlyRole(EXECUTOR_ROLE) {
        if (msg.value != value) revert WrongMsgValue();
        bytes32 id = operationId(target, value, data, salt);
        uint256 eta = queuedUntil[id];
        if (eta == 0) revert NotQueued();
        if (block.timestamp < eta) revert TooEarly();
        queuedUntil[id] = 0;
        bytes memory dataCopy = data;
        Address.functionCallWithValue(target, dataCopy, value);
        emit OperationExecuted(id, target, value, salt);
    }

    function cancel(bytes32 id) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (queuedUntil[id] == 0) revert NotQueued();
        queuedUntil[id] = 0;
        emit OperationCancelled(id);
    }

    receive() external payable {}
}

