// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { BRBJackpotFunder } from "../BRBJackpotFunder.sol";
import { UniswapV2TwapLib } from "../libraries/UniswapV2TwapLib.sol";

/// @dev Exposes internal TWAP / quote helpers for coverage without changing production bytecode paths.
contract BRBJackpotFunderHarness is BRBJackpotFunder {
    constructor(
        address engine_,
        address brb_,
        address router_,
        address jackpotTreasury_,
        address sideBet_,
        address admin
    ) BRBJackpotFunder(engine_, brb_, router_, jackpotTreasury_, sideBet_, admin) {}

    function harnessAmountOutMin(address asset, uint256 swapIn) external view returns (uint256) {
        address[] memory path = new address[](2);
        path[0] = asset;
        path[1] = address(brb);
        return _amountOutMin(asset, swapIn, path);
    }

    function harnessSetPairObservation(
        address pair,
        uint32 timestamp,
        uint256 price0Cumulative,
        uint256 price1Cumulative
    ) external {
        pairObservations[pair] = UniswapV2TwapLib.Observation({
            timestamp: timestamp,
            price0Cumulative: price0Cumulative,
            price1Cumulative: price1Cumulative
        });
    }

    function harnessSnapshotPairObservation(address asset) external {
        _snapshotPairObservation(asset);
    }

    function harnessPairFor(address asset) external view returns (address) {
        return _assetBrbPair(asset);
    }

    function harnessQuoteOut(address asset, uint256 swapIn) external view returns (uint256 quotedOut, bool usedTwap) {
        address pair = _assetBrbPair(asset);
        return _quoteOut(pair, asset, swapIn);
    }

    /// @dev Raw constant-product output at current reserves, to assert a TWAP floor sits above a
    /// manipulated spot price.
    function harnessSpotAmountOut(address asset, uint256 swapIn) external view returns (uint256) {
        return UniswapV2TwapLib.spotAmountOut(_assetBrbPair(asset), asset, swapIn);
    }
}

contracts/test/CoverageProbe.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { BankVault4626 } from "../BankVault4626.sol";
import { BRBJackpotFunder } from "../BRBJackpotFunder.sol";
import { RouletteEngine } from "../RouletteEngine.sol";
import { SideBet } from "../SideBet.sol";
import { ISideBet } from "../interfaces/ISideBet.sol";

/// @dev Executes guarded paths inside try/catch so revert branches register under solidity-coverage.
contract CoverageProbe {
    function tryBankInitialize(BankVault4626 vault, BankVault4626.InitializeParams calldata p) external returns (bool ok) {
        try vault.initialize(p) {
            ok = true;
        } catch {
            ok = false;
        }
    }

    function trySetSideBetController(BankVault4626 vault, address controller) external returns (bool ok) {
        try vault.setSideBetController(controller) {
            ok = true;
        } catch {
            ok = false;
        }
    }

    function trySetMinBet(BankVault4626 vault, uint256 minBet) external returns (bool ok) {
        try vault.setMinBet(minBet) {
            ok = true;
        } catch {
            ok = false;
        }
    }

    function tryPlaceBet(BankVault4626 vault, uint256 amount, bytes calldata betData, address referral)
        external
        returns (bool ok)
    {
